// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Also handles brick collisions to prevent tunneling.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const oldX = ball.x;
  const oldY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Bricks: physics check (moved from frame to prevent tunneling)
  let collided = false;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Tunneling check: if the ball moved so fast it jumped over the brick,
    // or if it's currently colliding.
    if (!collided && (collides(ball, brick) || 
        (Math.abs(ball.vx * dt) > 0 && 
         Math.abs(ball.vy * dt) > 0 && 
         ((oldY + ball.r > brick.y && ball.y - ball.r < brick.y + brick.h && 
           ((oldX + ball.r > brick.x && ball.x - ball.r < brick.x + brick.w))) ||
          (oldX + ball.r > brick.x && ball.x - ball.r < brick.x + brick.w &&
           ((oldY + ball.r > brick.y && ball.y - ball.r < brick.y + brick.h))))))) {

      collided = true;
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);

      const dx = ball.x - (brick.x + brick.w / 2);
      const dy = ball.y - (brick.y + brick.h / 2);
      const ox = (ball.r + brick.w / 2) - Math.abs(dx);
      const oy = (ball.r + brick.h / 2) - Math.abs(dy);

      if (ox < oy) {
        ball.vx *= -1;
        ball.x = dx > 0 ? brick.x + brick.w + ball.r : brick.x - ball.r;
      } else {
        ball.vy *= -1;
        ball.y = dy > 0 ? brick.y + brick.h + ball.r : brick.y - ball.r;
      }
    }
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0;
  }

  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

